<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_auth();$t=(int)$user['tenant_id'];if(!in_array($user['role_slug'],['clinic_admin'],true)){http_response_code(403);require APP_ROOT.'/app/views/403.php';exit;}$sub=\App\Core\Tenant::currentSubscription($t);$plans=db()->query("SELECT * FROM plans WHERE active=1 ORDER BY price_monthly")->fetchAll();$st=db()->prepare("SELECT COUNT(*) FROM patients WHERE tenant_id=:t AND status='active'");$st->execute(['t'=>$t]);$pc=(int)$st->fetchColumn();$st=db()->prepare("SELECT COUNT(*) FROM users WHERE tenant_id=:t AND active=1");$st->execute(['t'=>$t]);$uc=(int)$st->fetchColumn();layout('Plano',function()use($sub,$plans,$pc,$uc){?><div class="page-head"><div><span class="eyebrow">Assinatura</span><h1>Plano e limites</h1><p>A cobrança desta entrega está em modo manual; alterações são controladas pelo administrador SaaS.</p></div></div><div class="kpi-grid"><div class="kpi"><small>Plano atual</small><strong><?=e($sub['plan_name']??'—')?></strong></div><div class="kpi"><small>Status</small><strong><?=e($sub['status']??'—')?></strong></div><div class="kpi"><small>Pacientes ativos</small><strong><?=$pc?> / <?=e($sub['patient_limit']??'∞')?></strong></div><div class="kpi"><small>Usuários ativos</small><strong><?=$uc?> / <?=e($sub['user_limit']??'∞')?></strong></div></div><div class="pricing"><?php foreach($plans as $p):?><article class="price-card <?=($sub['plan_slug']??'')===$p['slug']?'popular':''?>"><h3><?=e($p['name'])?></h3><div class="price">R$ <?=number_format((float)$p['price_monthly'],2,',','.')?><small>/mês</small></div><p>Pacientes: <?=e($p['patient_limit']??'ilimitado')?> · usuários: <?=e($p['user_limit']??'ilimitado')?> · IA: <?=$p['ai_enabled']?'sim':'não'?></p><?php if(($sub['plan_slug']??'')===$p['slug']):?><span class="status active">Plano atual</span><?php endif?></article><?php endforeach?></div></section><?php },[]);
